//! Expand the exact K9 tail of T minus the certified 9,607-term sparse-R8
//! source combination, retaining labelled source provenance.

use std::collections::{BTreeMap,HashMap};
use std::env;
use std::fs::File;
use std::io::{self,BufRead,BufReader,Write};
use std::path::Path;
use std::time::Instant;

#[derive(Clone,Copy,Eq,Hash,Ord,PartialEq,PartialOrd)]struct Row12([u8;12]);
#[derive(Clone,Copy)]struct Action{sites:[u8;8],colours:[u8;3]}
#[derive(Clone)]struct Term{index:usize,coefficient:i64,word:u16,multiplier:[u8;8],source_column:usize,role:String}
struct Seed{anchors:[bool;252],actions:Vec<Action>,terms:Vec<Term>}
struct Engine{anchors:[bool;252],edge_id:[[u8;8];8],transforms:Vec<[u8;252]>,matchings:Vec<[(u8,u8);4]>}

fn fail(message:impl AsRef<str>)->!{eprintln!("expand-k9-tail: {}",message.as_ref());std::process::exit(2)}
fn nibble(b:u8)->u8{match b{b'0'..=b'9'=>b-b'0',b'a'..=b'f'=>b-b'a'+10,b'A'..=b'F'=>b-b'A'+10,_=>fail("bad hex")}}
fn parse_hex<const N:usize>(s:&str)->[u8;N]{if s.len()!=2*N{fail("bad hex length")}let b=s.as_bytes();let mut out=[0;N];for i in 0..N{out[i]=16*nibble(b[2*i])+nibble(b[2*i+1]);}out}
fn encode_word(s:&str)->u16{if s.len()!=8{fail("bad word")};s.bytes().fold(0,|code,digit|3*code+(digit-b'0')as u16)}
fn decode_word(mut code:u16)->[u8;8]{let mut w=[0;8];for i in(0..8).rev(){w[i]=(code%3)as u8;code/=3;}w}
fn hex<const N:usize>(row:&[u8;N])->String{const H:&[u8;16]=b"0123456789abcdef";let mut s=String::with_capacity(2*N);for b in row{s.push(H[(b>>4)as usize]as char);s.push(H[(b&15)as usize]as char)}s}

fn parse_seed(path:&Path)->io::Result<Seed>{let mut anchors=[false;252];let mut actions=Vec::new();let mut terms=Vec::new();for(number,line)in BufReader::new(File::open(path)?).lines().enumerate(){let line=line?;let f:Vec<_>=line.split_whitespace().collect();if f.is_empty(){continue}match f[0]{"KRENN_SPARSE_R8_K9_TAIL_TERMS_V1"=>if number!=0{fail("magic not first")},"ANCHORS"=>for cell in parse_hex::<12>(f[1]){anchors[cell as usize]=true},"ACTION"=>{let mut sites=[0;8];let mut colours=[0;3];for(i,b)in f[1].bytes().enumerate(){sites[i]=b-b'0'}for(i,b)in f[2].bytes().enumerate(){colours[i]=b-b'0'}actions.push(Action{sites,colours})},"TERM"=>terms.push(Term{index:f[1].parse().unwrap(),coefficient:f[2].parse().unwrap(),word:encode_word(f[3]),multiplier:parse_hex::<8>(f[4]),source_column:f[5].parse().unwrap(),role:f[6].to_string()}),_=>fail("unknown record")}}if actions.len()!=2304||terms.len()!=9607{fail("input count changed")};Ok(Seed{anchors,actions,terms})}
fn matchings()->Vec<[(u8,u8);4]>{fn rec(v:&[u8],p:&mut Vec<(u8,u8)>,o:&mut Vec<[(u8,u8);4]>){if v.is_empty(){o.push([p[0],p[1],p[2],p[3]]);return}for i in 1..v.len(){let mut r=Vec::new();r.extend_from_slice(&v[1..i]);r.extend_from_slice(&v[i+1..]);p.push((v[0],v[i]));rec(&r,p,o);p.pop();}}let mut o=Vec::new();rec(&[0,1,2,3,4,5,6,7],&mut Vec::new(),&mut o);o}

impl Engine{
 fn new(seed:&Seed)->Self{let mut cell_u=[0;252];let mut cell_v=[0;252];let mut cell_a=[0;252];let mut cell_b=[0;252];let mut edge_id=[[0;8];8];let mut edge=0u8;for u in 0..8u8{for v in u+1..8u8{edge_id[u as usize][v as usize]=edge;edge_id[v as usize][u as usize]=edge;for a in 0..3u8{for b in 0..3u8{let id=edge as usize*9+a as usize*3+b as usize;cell_u[id]=u;cell_v[id]=v;cell_a[id]=a;cell_b[id]=b}}edge+=1}}let cid=|u:u8,v:u8,a:u8,b:u8|->u8{(edge_id[u as usize][v as usize]as usize*9+a as usize*3+b as usize)as u8};let mut transforms=Vec::new();for action in &seed.actions{let mut t=[0;252];for id in 0..252{let(mut u,mut v)=(action.sites[cell_u[id]as usize],action.sites[cell_v[id]as usize]);let(mut a,mut b)=(action.colours[cell_a[id]as usize],action.colours[cell_b[id]as usize]);if u>v{std::mem::swap(&mut u,&mut v);std::mem::swap(&mut a,&mut b)}t[id]=cid(u,v,a,b)}transforms.push(t)}Self{anchors:seed.anchors,edge_id,transforms,matchings:matchings()}}
 fn cid(&self,u:u8,v:u8,a:u8,b:u8)->u8{(self.edge_id[u as usize][v as usize]as usize*9+a as usize*3+b as usize)as u8}
 fn degree(&self,cells:&[u8])->u8{cells.iter().map(|c|(!self.anchors[*c as usize])as u8).sum()}
 fn canonical(&self,row:Row12,cache:&mut HashMap<Row12,Row12>)->Row12{if let Some(&answer)=cache.get(&row){return answer}let mut best=None;for t in &self.transforms{let mut image=row.0.map(|c|t[c as usize]);image.sort_unstable();let candidate=Row12(image);if best.map_or(true,|old|candidate<old){best=Some(candidate)}}let answer=best.unwrap();if cache.len()<300_000{cache.insert(row,answer);}answer}
 fn term_row(&self,word:&[u8;8],matching:&[(u8,u8);4])->[u8;4]{let mut out=[0;4];for(i,&(u,v))in matching.iter().enumerate(){out[i]=self.cid(u,v,word[u as usize],word[v as usize])}out}
}

struct SourcePiece{sum:BTreeMap<Row12,i64>,ledger:Vec<(Term,Vec<(Row12,u8)>)>,emissions:usize}
fn expand_source(engine:&Engine,terms:&[Term],workers:usize)->SourcePiece{let chunk=terms.len().div_ceil(workers);let mut pieces=Vec::new();std::thread::scope(|scope|{let mut handles=Vec::new();for worker in 0..workers{let start=worker*chunk;let end=((worker+1)*chunk).min(terms.len());if start>=end{continue}handles.push(scope.spawn(move||{let begun=Instant::now();let mut sum=BTreeMap::new();let mut ledger=Vec::new();let mut cache=HashMap::new();let mut emissions=0;for term in &terms[start..end]{let word=decode_word(term.word);let md=engine.degree(&term.multiplier);let mut outputs:BTreeMap<Row12,u8>=BTreeMap::new();for matching in &engine.matchings{let selected=engine.term_row(&word,matching);if md+engine.degree(&selected)!=9{continue}let mut row=[0;12];row[..8].copy_from_slice(&term.multiplier);row[8..].copy_from_slice(&selected);row.sort_unstable();let canonical=engine.canonical(Row12(row),&mut cache);*outputs.entry(canonical).or_default()+=1;emissions+=1;}for(&row,&count)in &outputs{*sum.entry(row).or_default()+=term.coefficient*count as i64}if !outputs.is_empty(){ledger.push((term.clone(),outputs.into_iter().collect()));}}eprintln!("source worker={start}..{end} emissions={emissions} rows={} terms={} elapsed={:.3}s",sum.len(),ledger.len(),begun.elapsed().as_secs_f64());SourcePiece{sum,ledger,emissions}}));}for handle in handles{pieces.push(handle.join().unwrap_or_else(|_|fail("source worker panic")))}});let mut answer=SourcePiece{sum:BTreeMap::new(),ledger:Vec::new(),emissions:0};for piece in pieces{answer.emissions+=piece.emissions;for(row,value)in piece.sum{*answer.sum.entry(row).or_default()+=value}answer.ledger.extend(piece.ledger)}answer.ledger.sort_by_key(|(term,_)|term.index);answer}

fn expand_target(engine:&Engine,workers:usize)->(BTreeMap<Row12,i64>,usize){let mut pure:Vec<Vec<([u8;4],u8)>>=Vec::new();for colour in 0..3u8{let word=[colour;8];pure.push(engine.matchings.iter().map(|m|{let row=engine.term_row(&word,m);let degree=engine.degree(&row);(row,degree)}).collect())}let chunk=105usize.div_ceil(workers);let mut pieces=Vec::new();std::thread::scope(|scope|{let mut handles=Vec::new();for worker in 0..workers{let start=worker*chunk;let end=((worker+1)*chunk).min(105);if start>=end{continue}let pure_ref=&pure;handles.push(scope.spawn(move||{let begun=Instant::now();let mut out:BTreeMap<Row12,i64>=BTreeMap::new();let mut cache=HashMap::new();let mut emissions=0;for i in start..end{for j in 0..105{for k in 0..105{let(a,da)=pure_ref[0][i];let(b,db)=pure_ref[1][j];let(c,dc)=pure_ref[2][k];if da+db+dc!=9{continue}let mut row=[0;12];row[..4].copy_from_slice(&a);row[4..8].copy_from_slice(&b);row[8..].copy_from_slice(&c);row.sort_unstable();let canonical=engine.canonical(Row12(row),&mut cache);*out.entry(canonical).or_default()+=1;emissions+=1;}}}eprintln!("target worker={start}..{end} emissions={emissions} rows={} elapsed={:.3}s",out.len(),begun.elapsed().as_secs_f64());(out,emissions)}));}for handle in handles{pieces.push(handle.join().unwrap_or_else(|_|fail("target worker panic")))}});let mut out:BTreeMap<Row12,i64>=BTreeMap::new();let mut emissions=0;for(piece,count)in pieces{emissions+=count;for(row,value)in piece{*out.entry(row).or_default()+=value}}(out,emissions)}

fn write_ledger(path:&Path,source:&SourcePiece)->io::Result<()>{let mut out=File::create(path)?;writeln!(out,"{{\"format\":\"krenn-sparse-r8-k9-source-tail-ledger-v1\",\"firing_terms\":{},\"literal_emissions\":{},\"type\":\"header\"}}",source.ledger.len(),source.emissions)?;for(term,rows)in &source.ledger{write!(out,"{{\"coefficient\":{},\"index\":{},\"multiplier\":\"{}\",\"outputs\":[",term.coefficient,term.index,hex(&term.multiplier))?;for(i,(row,count))in rows.iter().enumerate(){if i!=0{write!(out,",")?}write!(out,"[\"{}\",{}]",hex(&row.0),count)?}writeln!(out,"],\"role\":{:?},\"source_closure_column\":{},\"type\":\"source_term\",\"word\":\"{}\"}}",term.role,term.source_column,decode_word(term.word).iter().map(|d|(b'0'+*d)as char).collect::<String>())?;}Ok(())}

fn write_result(path:&Path,target:&BTreeMap<Row12,i64>,source:&SourcePiece,tail:&BTreeMap<Row12,i64>,target_emissions:usize,elapsed:f64)->io::Result<()>{let mut out=File::create(path)?;write!(out,"{{\n  \"status\":\"UNAUDITED exact integer quotient K9 tail expansion\",\n  \"formula\":\"E9=(H0H1H2)_K9-(certified 9607-term source combination)_K9\",\n  \"target_literal_emissions\":{target_emissions},\n  \"target_row_orbits\":{},\n  \"source_literal_emissions\":{},\n  \"source_firing_terms\":{},\n  \"source_row_orbits\":{},\n  \"tail_row_orbits\":{},\n  \"elapsed_seconds\":{elapsed:.6},\n  \"tail\":[",target.len(),source.emissions,source.ledger.len(),source.sum.len(),tail.len())?;for(i,(row,value))in tail.iter().enumerate(){if i!=0{write!(out,",")?}write!(out,"[\"{}\",{}]",hex(&row.0),value)?}write!(out,"]\n}}\n")?;Ok(())}

fn main(){let args:Vec<_>=env::args().collect();if args.len()!=4{eprintln!("usage: expand_k9_tail INPUT.txt RESULTS.json LEDGER.jsonl");std::process::exit(2)}let begun=Instant::now();let seed=parse_seed(Path::new(&args[1])).unwrap_or_else(|e|fail(e.to_string()));let engine=Engine::new(&seed);let workers=std::thread::available_parallelism().map_or(4,|v|v.get()).min(8);let source=expand_source(&engine,&seed.terms,workers);let(target,target_emissions)=expand_target(&engine,workers);let mut tail=target.clone();for(&row,&value)in &source.sum{*tail.entry(row).or_default()-=value}tail.retain(|row,value|{if engine.degree(&row.0)!=9{fail("tail row left K9")};*value!=0});write_ledger(Path::new(&args[3]),&source).unwrap_or_else(|e|fail(e.to_string()));write_result(Path::new(&args[2]),&target,&source,&tail,target_emissions,begun.elapsed().as_secs_f64()).unwrap_or_else(|e|fail(e.to_string()));eprintln!("PASS target_emissions={target_emissions} target_rows={} source_emissions={} source_rows={} tail_rows={} elapsed={:.3}s",target.len(),source.emissions,source.sum.len(),tail.len(),begun.elapsed().as_secs_f64());}
